// Pole + pole-painting math — ported VERBATIM from SignEstimate Pro
// (NewFoundationEstimate.jsx: polesTotal / calcPolePaintingCost /
//  getPolePaintingSizeMultiplier). Poles are PROJECT-level, not per foundation item.
//
// Availability hardening: a missing price, malformed dimension, or invalid
// painting setting is not a free pole — the row is held with its acknowledged
// snapshot amounts and reported instead of silently repricing to $0.
//
// CMP-E01/O-056 consolidation: project-level `poles[]` is the single priced
// representation. The legacy per-item pole fields (`selected_pole_id`,
// `pole_total_height_inches`, `pole_offset_from_bottom_inches`, item-level
// `include_pole_painting`, and the dead `pole_cost`/`pole_painting_cost`
// snapshots) are NEVER priced — they derive advisory `legacy_item` rows via
// consolidateFoundationPoles and move onto the canonical list only through the
// explicit migrateLegacyItemPole step. A row marked pole_origin "legacy_item"
// that reaches the priced path is held, never silently repriced.
//
// CMP-E02/O-057 geometry: foundationPoleGeometry resolves five DISTINCT
// quantities that used to be conflated into height_inches + y_offset_inches —
// height above grade, embedment below grade (canonical `embedment_inches`,
// legacy `y_offset_inches` is the same quantity's old spelling), vertical base
// offset above grade (`base_offset_inches`, placement only — never material
// length), plan offset (x_inches/z_inches), and the explicit total stock
// length (`total_length_inches`, the billed length when recorded; otherwise
// the billed length is height + embedment). The actual cross-section shape
// (`pole_shape`, authored then catalog) is carried distinctly — the priced
// math below is unchanged for rows that record none of the new fields.

const assignedId = value => (typeof value === "string" && value.trim() !== "")
  || (typeof value === "number" && Number.isFinite(value));

// Inventory normalization boundary (CMP-A08): the canonical settings pick and
// price/dimension/measurement kernels live in
// masterInventory/inventoryNormalization.
//   poleSettingValue      — explicit-0-respecting pick (same semantics as wallSettingValue)
//   polePriceNumber       — catalog/customer price basis: finite, nonnegative
//                           (explicit 0 is a valid free price)
//   poleDimensionNumber   — positive finite dimension in inches/feet (height
//                           above grade, stock length, pole width)
//   poleOffsetNumber      — finite nonnegative measurement (depth in ground may
//                           legitimately be zero; negatives are not lengths)
//   poleSettingNumber / polePositiveSettingNumber — setting compositions;
//                           missing/blank settings keep the module default,
//                           recorded values must parse on the basis.
//   poleFiniteNumber      — finite signed basis (legacy field presence checks)
import {
  inventorySettingValue as poleSettingValue,
  inventoryNonnegativeNumber as polePriceNumber,
  inventoryPositiveNumber as poleDimensionNumber,
  inventoryNonnegativeMeasurement as poleOffsetNumber,
  inventorySettingNumber as poleSettingNumber,
  inventoryPositiveSettingNumber as polePositiveSettingNumber,
  inventoryFiniteNumber as poleFiniteNumber,
} from "@/components/masterInventory/inventoryNormalization";

const setting = (settings, key, def) => parseFloat(poleSettingValue(settings?.[key], def));

const POLE_PAINT_SETTING_DEFAULTS = {
  pole_paint_cost_per_lf: 3.5,
  pole_paint_labor_per_lf: 2.5,
  pole_paint_size_multiplier_12in: 2.0,
  pole_paint_size_multiplier_10in: 1.75,
  pole_paint_size_multiplier_8in: 1.5,
  pole_paint_size_multiplier_6in: 1.25,
  pole_paint_size_multiplier_4in: 1.0,
};

const polePaintMultiplierKey = (widthInches) => {
  const w = widthInches === null ? 6 : widthInches;
  if (w >= 12) return "pole_paint_size_multiplier_12in";
  if (w >= 10) return "pole_paint_size_multiplier_10in";
  if (w >= 8) return "pole_paint_size_multiplier_8in";
  if (w >= 6) return "pole_paint_size_multiplier_6in";
  return "pole_paint_size_multiplier_4in";
};

const getPolePaintingSizeMultiplier = (inv, settings) => {
  const w = inv?.pole_width_inches || 6;
  if (w >= 12) return setting(settings, "pole_paint_size_multiplier_12in", 2.0);
  if (w >= 10) return setting(settings, "pole_paint_size_multiplier_10in", 1.75);
  if (w >= 8) return setting(settings, "pole_paint_size_multiplier_8in", 1.5);
  if (w >= 6) return setting(settings, "pole_paint_size_multiplier_6in", 1.25);
  return setting(settings, "pole_paint_size_multiplier_4in", 1.0);
};

export const calcPolePaintingCost = (p, inv, settings) => {
  if (!p.include_pole_painting || !inv) return 0;
  // Total pole length = height above ground + depth in ground.
  const heightFt = ((p.height_inches || 0) + (p.y_offset_inches || 0)) / 12;
  const paintCostPerLf = setting(settings, "pole_paint_cost_per_lf", 3.5);
  const paintLaborPerLf = setting(settings, "pole_paint_labor_per_lf", 2.5);
  const sizeMult = getPolePaintingSizeMultiplier(inv, settings);
  return heightFt * (paintCostPerLf + paintLaborPerLf) * sizeMult;
};

// ─── Canonical pole geometry (CMP-E02 / O-057) ──────────────────────────────
//
// Known cross-section values; a recorded string outside this set is still
// carried verbatim (shape is geometry metadata, not yet a priced quantity) —
// only a non-string recording is malformed authored data and holds the row.
export const POLE_SHAPE_VALUES = ["round", "square", "rectangular", "elliptical", "other"];

// A recorded value is present data; undefined/null/"" are absent (blank is
// "not authored", matching the draft-input boundary).
const recorded = (v) => v !== undefined && v !== null && v !== "";

// Resolve the distinct pole quantities into one model. Returns:
//   height_above_grade_inches — pole dimension above finished grade (required)
//   embedment_inches          — depth below grade; canonical embedment_inches,
//                               legacy y_offset_inches is the same quantity
//   base_offset_inches        — pole base above grade (wall/pier mounting);
//                               placement metadata, never material length
//   plan_offset_inches        — plan position x/z (lenient finite-or-0, the
//                               same basis the layout canvas/preview consume)
//   total_length_inches       — explicit billed/purchased stock length override
//   required_length_inches    — billed material length: explicit total, else
//                               height + embedment (the unchanged ported basis)
//   pole_shape                — actual cross-section (authored > catalog), or
//                               null when unspecified — never invented
//   cross_section             — catalog width/depth/wall-thickness for shape
//   sources                   — which field supplied each quantity
//   problems                  — [{field, code, message}] for the caller to map
//                               onto held-row issues (never repriced silently)
export function foundationPoleGeometry(pole, inv = null) {
  const p = pole ?? {};
  const problems = [];
  const add = (field, code, message) => problems.push({ field, code, message });

  // Height above grade — a distinct, always-required quantity.
  const height = poleDimensionNumber(p.height_inches);
  const heightSource = height !== null ? "height_inches" : "unavailable";
  if (height === null) {
    add("height_inches", "pole_height_unavailable",
      "record a positive, finite height above grade in inches before repricing");
  }

  // Embedment below grade — canonical embedment_inches; y_offset_inches is
  // the legacy spelling of the SAME quantity (the panel labeled it "depth in
  // ground" and the priced length has always included it). Both recorded and
  // resolving differently is ambiguous authored data — held, never picked.
  const canonEmbedRaw = p.embedment_inches;
  const legacyEmbedRaw = p.y_offset_inches;
  const canonEmbedPresent = recorded(canonEmbedRaw);
  const legacyEmbedPresent = recorded(legacyEmbedRaw);
  let embedment = null;
  let embedmentSource = "unavailable";
  if (canonEmbedPresent) {
    embedment = poleOffsetNumber(canonEmbedRaw);
    if (embedment === null) {
      add("embedment_inches", "pole_embedment_unavailable",
        "record a finite, nonnegative embedment below grade in inches before repricing");
    } else {
      embedmentSource = "embedment_inches";
    }
  }
  if (legacyEmbedPresent) {
    const legacy = poleOffsetNumber(legacyEmbedRaw);
    if (!canonEmbedPresent) {
      embedment = legacy;
      if (legacy === null) {
        add("y_offset_inches", "pole_depth_unavailable",
          "record a finite, nonnegative depth in ground in inches before repricing");
      } else {
        embedmentSource = "y_offset_inches";
      }
    } else if (embedment !== null && legacy !== null && legacy !== embedment) {
      add("embedment_inches", "pole_embedment_conflict",
        "embedment and legacy depth-in-ground record different values — clear one before repricing");
    }
  }
  if (!canonEmbedPresent && !legacyEmbedPresent) {
    add("y_offset_inches", "pole_depth_unavailable",
      "record a finite, nonnegative depth in ground in inches before repricing");
  }

  // Vertical base offset — where the pole's base sits relative to grade
  // (e.g. wall-top mounting). Placement metadata only: it never contributes
  // to required material length.
  const baseRaw = p.base_offset_inches;
  let baseOffset = 0;
  let baseSource = "default";
  if (recorded(baseRaw)) {
    baseOffset = poleOffsetNumber(baseRaw);
    if (baseOffset === null) {
      add("base_offset_inches", "pole_base_offset_unavailable",
        "record a finite, nonnegative base offset above grade in inches or clear it before repricing");
    } else {
      baseSource = "base_offset_inches";
    }
  }

  // Explicit total stock length — the purchased/billed stick length. When
  // recorded it is the billed length; it must cover height + embedment or the
  // pole cannot physically reach its recorded embedment.
  const totalRaw = p.total_length_inches;
  let total = null;
  let totalSource = "derived";
  if (recorded(totalRaw)) {
    total = poleDimensionNumber(totalRaw);
    if (total === null) {
      add("total_length_inches", "pole_total_length_unavailable",
        "record a positive, finite total stock length in inches or clear it before repricing");
    } else {
      totalSource = "total_length_inches";
    }
  }

  // Billed material length — the unchanged ported basis (height + embedment)
  // unless an explicit total stock length overrides it.
  let required = null;
  if (totalSource === "total_length_inches" && total !== null) {
    required = total;
    if (height !== null && embedment !== null && total < height + embedment) {
      add("total_length_inches", "pole_total_length_conflict",
        "total stock length is shorter than height above grade plus embedment — lengthen it or clear it before repricing");
    }
  } else if (height !== null && embedment !== null) {
    required = height + embedment;
  }

  // Actual cross-section — authored pole_shape wins over the catalog row's
  // pole_shape; an unspecified shape stays null (unspecified is legitimate —
  // the renderers assume round today and no claim otherwise is made). A
  // recorded non-string is malformed authored data and holds the row.
  const authoredShapePresent = recorded(p.pole_shape);
  const shapeRaw = authoredShapePresent ? p.pole_shape : inv?.pole_shape;
  let shape = null;
  let shapeSource = null;
  let shapeKnown = false;
  if (recorded(shapeRaw)) {
    if (typeof shapeRaw !== "string") {
      add("pole_shape", "pole_shape_unavailable",
        "recorded pole shape must be a value like round or square — clear or correct it before repricing");
    } else {
      shape = shapeRaw.trim().toLowerCase();
      shapeSource = authoredShapePresent ? "pole_shape" : "catalog";
      shapeKnown = POLE_SHAPE_VALUES.includes(shape);
    }
  }
  const cross_section = inv == null ? null : {
    shape,
    width_inches: poleOffsetNumber(inv.pole_width_inches),
    depth_inches: poleOffsetNumber(inv.pole_depth_inches),
    wall_thickness_inches: poleOffsetNumber(inv.pole_wall_thickness_inches),
  };

  // Plan offset — the same finite-or-0 basis the layout canvas and preview
  // consume (placement only, never material length).
  const planOffset = {
    x_inches: poleFiniteNumber(p.x_inches) ?? 0,
    z_inches: poleFiniteNumber(p.z_inches) ?? 0,
  };

  return {
    height_above_grade_inches: height,
    embedment_inches: embedment,
    base_offset_inches: baseOffset,
    plan_offset_inches: planOffset,
    total_length_inches: total,
    required_length_inches: required,
    pole_shape: shape,
    pole_shape_known: shapeKnown,
    cross_section,
    sources: {
      height_above_grade: heightSource,
      embedment: embedmentSource,
      base_offset: baseSource,
      total_length: totalSource,
      shape: shapeSource,
    },
    problems,
  };
}

// ─── Legacy item-pole consolidation (CMP-E01 / O-056) ───────────────────────
//
// The single priced representation is project.poles. Item rows can still carry
// the pre-CMP fields below; they are ghost data (rendered in the 3D preview,
// never priced — item_total_cost has no pole term and sumPole reads only
// project poles). These helpers expose them as advisory derived rows and move
// them onto the canonical list only through the explicit migrate step, so a
// physical pole is never billed twice and never silently loses geometry.
export const POLE_ORIGIN_PROJECT = "project";
export const POLE_ORIGIN_LEGACY_ITEM = "legacy_item";
export const LEGACY_ITEM_POLE_FIELDS = [
  "selected_pole_id", "pole_total_height_inches", "pole_offset_from_bottom_inches",
  "include_pole_painting",
];

const isCostSnapshot = (v) => typeof v === "number" && Number.isFinite(v);

// An item "carries" a legacy pole when any pole field departs from the
// blankItem defaults — including the dead pole_cost/pole_painting_cost
// snapshots, which prove a pole once existed even if the selection was lost.
export function itemHasLegacyPole(item) {
  if (!item || typeof item !== "object") return false;
  const id = item.selected_pole_id;
  if (assignedId(id)) return true;
  const height = poleFiniteNumber(item.pole_total_height_inches);
  if (height !== null && height !== 0) return true;
  const offBottom = poleFiniteNumber(item.pole_offset_from_bottom_inches);
  if (offBottom !== null && offBottom !== 0) return true;
  if (item.include_pole_painting === true) return true;
  if (isCostSnapshot(item.pole_cost) || isCostSnapshot(item.pole_painting_cost)) return true;
  return false;
}

// Advisory derived view of one item's legacy pole fields — marked
// pole_origin "legacy_item" so it can never enter the priced list silently.
// `height_inches` is null when the legacy total height is absent/malformed;
// embedment is intentionally absent (not derivable — see migrate below).
export function deriveLegacyItemPole(item, index = 0) {
  if (!itemHasLegacyPole(item)) return null;
  const height = poleFiniteNumber(item.pole_total_height_inches);
  const offBottom = poleFiniteNumber(item.pole_offset_from_bottom_inches);
  return {
    pole_origin: POLE_ORIGIN_LEGACY_ITEM,
    source_item_index: index,
    source_item_component_id: item.component_id ?? null,
    foundation_component_id: item.component_id ?? "",
    foundation_idx: index,
    pole_id: assignedId(item.selected_pole_id) ? item.selected_pole_id : "",
    height_inches: height !== null && height > 0 ? height : null,
    include_pole_painting: item.include_pole_painting === true,
    legacy_pole_offset_from_bottom_inches: offBottom,
    legacy_pole_cost: isCostSnapshot(item.pole_cost) ? item.pole_cost : null,
    legacy_pole_painting_cost: isCostSnapshot(item.pole_painting_cost) ? item.pole_painting_cost : null,
  };
}

// Consolidated pole model for one project (or any {items, poles} source):
//   poles       — the canonical, priced list (same row refs, never mutated)
//   legacyPoles — advisory rows derived from item-level fields
//   overlaps    — [{derivedIndex, poleIndex, ...}] where a project pole is
//                 already assigned to the same foundation; surfaced for review
//                 rather than silently deduplicated (two poles on one footing
//                 are legitimate)
//   issues      — advisory-only; `severity: "advisory"` keeps them out of the
//                 priced-issue channels that gate save/handoff
export function consolidateFoundationPoles(source = {}) {
  const items = Array.isArray(source?.items) ? source.items : [];
  const poles = Array.isArray(source?.poles) ? source.poles : [];
  const legacyPoles = [];
  const overlaps = [];
  const issues = [];
  items.forEach((item, index) => {
    const derived = deriveLegacyItemPole(item, index);
    if (!derived) return;
    const derivedIndex = legacyPoles.length;
    legacyPoles.push(derived);
    issues.push({
      kind: "pole", severity: "advisory", code: "legacy_item_pole_fields",
      componentId: item?.component_id ?? null, field: "selected_pole_id",
      message: `Foundation ${index + 1} carries legacy item-pole fields that are not priced — migrate them into the Poles section or clear them.`,
    });
    poles.forEach((p, poleIndex) => {
      // Overlap = this project pole is assigned to this foundation item —
      // by component id when both sides carry one, otherwise by the
      // foundation_idx slot (which is itself an assignment signal even when
      // the component id side is missing).
      const assignedToItem = p?.foundation_component_id && item?.component_id
        ? p.foundation_component_id === item.component_id
        : p?.foundation_idx !== undefined && p?.foundation_idx !== null
          && p.foundation_idx === index;
      if (assignedToItem) {
        overlaps.push({
          derivedIndex, poleIndex,
          itemComponentId: item?.component_id ?? null,
          poleComponentId: p?.component_id ?? null,
        });
      }
    });
  });
  const overlappedItems = new Set(overlaps.map((o) => o.derivedIndex));
  for (const derivedIndex of overlappedItems) {
    const count = overlaps.filter((o) => o.derivedIndex === derivedIndex).length;
    const itemIndex = legacyPoles[derivedIndex]?.source_item_index ?? derivedIndex;
    issues.push({
      kind: "pole", severity: "advisory", code: "pole_representation_overlap",
      componentId: legacyPoles[derivedIndex]?.source_item_component_id ?? null,
      field: "selected_pole_id",
      message: `Foundation ${itemIndex + 1} has legacy item-pole fields and ${count} project pole(s) on the same foundation — verify they describe different physical poles before migrating.`,
    });
  }
  return { poles, legacyPoles, overlaps, issues };
}

// The explicit consolidation step: build the canonical project-pole row from
// an item's legacy fields plus the patch that clears them. The returned pole
// deliberately leaves embedment unrecorded — pole_offset_from_bottom_inches is
// ambiguous (offset above the footing bottom, not a depth in ground), so it is
// preserved verbatim as legacy_pole_offset_from_bottom_inches and the priced
// row holds on pole_depth_unavailable until a real embedment is recorded.
// Plan position inherits the foundation item's recorded x/z placement.
export function migrateLegacyItemPole(item, index = 0, { createId } = {}) {
  if (!itemHasLegacyPole(item)) return null;
  const height = poleFiniteNumber(item.pole_total_height_inches);
  const offBottom = poleFiniteNumber(item.pole_offset_from_bottom_inches);
  const planX = poleFiniteNumber(item.x_inches);
  const planZ = poleFiniteNumber(item.z_inches);
  const pole = {
    ...(typeof createId === "function" ? { component_id: createId("pole") } : {}),
    pole_id: assignedId(item.selected_pole_id) ? item.selected_pole_id : "",
    ...(height !== null && height > 0 ? { height_inches: height } : {}),
    include_pole_painting: item.include_pole_painting === true,
    foundation_component_id: item.component_id ?? "",
    foundation_idx: index,
    ...(planX !== null ? { x_inches: planX } : {}),
    ...(planZ !== null ? { z_inches: planZ } : {}),
    migrated_from: POLE_ORIGIN_LEGACY_ITEM,
    source_item_component_id: item.component_id ?? undefined,
    ...(offBottom !== null ? { legacy_pole_offset_from_bottom_inches: offBottom } : {}),
  };
  const itemPatch = {
    selected_pole_id: "",
    pole_total_height_inches: 0,
    pole_offset_from_bottom_inches: 0,
    include_pole_painting: false,
    // The dead item-level snapshots clear too — leaving them would keep the
    // item flagged as carrying a legacy pole after its explicit migration.
    pole_cost: undefined,
    pole_painting_cost: undefined,
  };
  return { pole, itemPatch };
}

// Resolves the catalog row and every value the pricing formulas read, on a
// normalized calculation copy — authored rows and settings are never mutated.
function polePricing(pole, inventory = [], index = 0, settings = {}) {
  const issues = [];
  const id = pole?.pole_id;
  const paint = { costPerLf: null, laborPerLf: null, sizeMultiplier: null };
  const add = (field, code, message) => issues.push({
    kind: "pole", index, componentId: pole?.component_id ?? pole?.id ?? null,
    field, inventoryId: assignedId(id) ? id : null, code,
    message: `Pole ${index + 1}: ${message}.`,
  });
  // Fail closed on the legacy representation: a row marked legacy_item must
  // never reach the priced list — migrate it through migrateLegacyItemPole or
  // it stays held (a silent price here would double-charge the ghost pole).
  if (pole?.pole_origin === POLE_ORIGIN_LEGACY_ITEM) {
    add("pole_origin", "pole_legacy_representation",
      "legacy item-pole data cannot price here — migrate it into the Poles section or remove it");
    return { issues, inv: null, geometry: null, painting: false, rate: null, stockLengthInches: null, widthInches: null, paint };
  }
  let inv = null;
  if (!assignedId(id)) {
    add("pole_id", "catalog_item_unassigned", "select a catalog material");
  } else {
    const matches = inventory.filter((row) => row?.id === id);
    if (!matches.length) {
      add("pole_id", "catalog_item_unavailable", "selected catalog material is unavailable");
    } else if (matches.length !== 1) {
      add("pole_id", "catalog_item_ambiguous", "selected catalog material is ambiguous");
    } else if (matches[0].material_type !== "pole") {
      add("pole_id", "catalog_item_type_mismatch", "selected catalog material is not a pole");
    } else {
      inv = matches[0];
    }
  }
  // Distinct authored/calculated quantities (CMP-E02). The height and
  // depth-in-ground checks map onto the geometry problems unchanged — same
  // codes and messages as the pre-consolidation checks.
  const geometry = foundationPoleGeometry(pole, inv);
  for (const problem of geometry.problems) add(problem.field, problem.code, problem.message);
  const painting = pole?.include_pole_painting === true;
  let rate = null;
  let stockLengthInches = null;
  let widthInches = null;
  if (inv) {
    const override = pole?.custom_cost_per_unit;
    const hasOverride = override !== undefined && override !== null;
    const stockMode = inv.pole_pricing_mode === "stock_price";
    rate = polePriceNumber(hasOverride ? override : (stockMode ? inv.pole_stock_price : inv.cost_per_unit));
    if (rate === null) {
      add(hasOverride ? "custom_cost_per_unit" : stockMode ? "pole_stock_price" : "cost_per_unit",
        "pole_price_unavailable", "record a finite, nonnegative pole price before repricing");
    }
    if (stockMode) {
      const stockLengthFt = polePositiveSettingNumber(inv.pole_stock_length_ft, 20);
      if (stockLengthFt === null) {
        add("pole_stock_length_ft", "pole_stock_length_unavailable",
          "the selected catalog stock length must be a recorded finite positive number");
      } else {
        stockLengthInches = stockLengthFt * 12;
      }
    }
    if (painting) {
      widthInches = polePositiveSettingNumber(inv.pole_width_inches, 6);
      if (widthInches === null) {
        add("pole_width_inches", "pole_width_unavailable",
          "the selected catalog pole width must be a recorded finite positive number");
      }
      const paintSetting = (key, label) => {
        const value = poleSettingNumber(settings?.[key], POLE_PAINT_SETTING_DEFAULTS[key]);
        if (value === null) {
          add(key, "pole_paint_setting_unavailable",
            `record a finite, nonnegative ${label} before repricing`);
        }
        return value;
      };
      paint.costPerLf = paintSetting("pole_paint_cost_per_lf", "pole paint cost per LF");
      paint.laborPerLf = paintSetting("pole_paint_labor_per_lf", "pole paint labor per LF");
      paint.sizeMultiplier = paintSetting(polePaintMultiplierKey(widthInches), "pole paint size multiplier");
    }
  }
  return { issues, inv, geometry, painting, rate, stockLengthInches, widthInches, paint };
}

export function foundationPolePricingIssues(pole, inventory = [], index = 0, settings = {}) {
  return polePricing(pole, inventory, index, settings).issues;
}

export function foundationPoleCatalogIssues(poles = [], inventory = [], settings = {}) {
  return (poles || []).flatMap((pole, index) => foundationPolePricingIssues(pole, inventory, index, settings));
}

export function calcPoles(poles = [], inventory = [], settings = {}, options = {}) {
  const explicitSnapshot = options != null && Object.prototype.hasOwnProperty.call(options, "savedPoles");
  const savedPoles = Array.isArray(options?.savedPoles) ? options.savedPoles : [];
  const counts = rows => {
    const out = new Map();
    for (const row of rows) {
      const id = row?.component_id;
      if (assignedId(id)) out.set(id, (out.get(id) || 0) + 1);
    }
    return out;
  };
  const currentCounts = counts(poles), savedCounts = counts(savedPoles);
  const savedById = new Map(savedPoles.filter((row) => assignedId(row?.component_id))
    .map((row) => [row.component_id, row]));
  // Preserve the last saved amounts, not a fabricated free pole. The project
  // availability gate prevents these historical values becoming a new quote.
  const held = pole => {
    const id = pole?.component_id;
    const acknowledged = explicitSnapshot
      ? assignedId(id) && currentCounts.get(id) === 1 && savedCounts.get(id) === 1
        ? savedById.get(id) : null
      : pole;
    const result = { ...pole };
    if (explicitSnapshot) {
      // Calculated snapshot fields only — authored fields ride on the spread.
      for (const field of ["pole_name", "pole_cost", "pole_painting_cost", "total_cost",
        "required_length_inches", "stock_pieces"]) {
        if (acknowledged && Object.prototype.hasOwnProperty.call(acknowledged, field)) result[field] = acknowledged[field];
        else delete result[field];
      }
    }
    return result;
  };
  const results = (poles || []).map((pole, index) => polePricing(pole, inventory, index, settings));
  return {
    poles: results.map((check, index) => {
      const pole = poles[index];
      if (check.issues.length) return held(pole);
      const { inv, geometry, rate, stockLengthInches, widthInches, paint } = check;
      const requiredInches = geometry.required_length_inches;
      let poleCost;
      let stockPieces = null;
      if (inv.pole_pricing_mode === "stock_price") {
        stockPieces = Math.ceil(requiredInches / stockLengthInches);
        poleCost = stockPieces * rate;
      } else {
        poleCost = (requiredInches / 12) * rate;
      }
      // The guarded path reuses the ported painting math on the normalized
      // calculation copy, so valid inputs price identically to the original.
      // The painted length is the billed required length — the whole stick.
      const paintingCost = check.painting
        ? calcPolePaintingCost(
            { include_pole_painting: true, height_inches: requiredInches, y_offset_inches: 0 },
            { ...inv, pole_width_inches: widthInches },
            {
              pole_paint_cost_per_lf: paint.costPerLf,
              pole_paint_labor_per_lf: paint.laborPerLf,
              [polePaintMultiplierKey(widthInches)]: paint.sizeMultiplier,
            })
        : 0;
      return {
        ...pole,
        // Resolved-geometry snapshots (CMP-E02): the canonical embedment
        // materializes alongside the authored legacy spelling; required
        // length, stock pieces, base offset and resolved shape persist so the
        // BOM, preview and handoff read the same distinct quantities.
        embedment_inches: geometry.embedment_inches,
        base_offset_inches: geometry.base_offset_inches,
        required_length_inches: requiredInches,
        stock_pieces: stockPieces,
        ...(geometry.pole_shape !== null ? { pole_shape: geometry.pole_shape } : {}),
        pole_name: inv.material_name || "",
        pole_cost: poleCost,
        pole_painting_cost: paintingCost,
        total_cost: poleCost + paintingCost,
      };
    }),
    polePricing: results.map((check) => ({
      available: check.issues.length === 0,
      issues: check.issues,
      // Resolved canonical geometry for display surfaces (never priced again).
      geometry: check.geometry,
    })),
  };
}

import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { inventoryDraftInput } from "@/components/masterInventory/inventoryNormalization";
import { Trash2, Plus } from "lucide-react";
import { money } from "./foundationCalc";
import { hasFoundationCostSnapshot } from "./foundationCatalogIntegrity";
import {
  POLE_SHAPE_VALUES,
  consolidateFoundationPoles,
} from "./poleCalculator";

// Blank-preserving project-entry draft, delegated to the boundary (CMP-A08).
const heightInput = inventoryDraftInput;

// CMP-E01/O-056: the project-level poles list below is the single priced
// representation. Items can still carry pre-consolidation pole fields; they
// surface here as an advisory (never priced — no double charge) and move onto
// the canonical list only through the explicit onMigrateItemPole callback.
// CMP-E02/O-057: the inputs keep the five distinct quantities separate —
// height above grade, embedment below grade (canonical `embedment_inches`;
// a legacy row's `y_offset_inches` migrates into it on edit), vertical base
// offset, and explicit total stock length — with the actual shape carried on
// `pole_shape`.
export default function FoundationPolesPanel({ poles = [], options = [], items = [], onChange, polePricing = [], onMigrateItemPole }) {
  const patchPole = (index, changes) =>
    onChange(poles.map((p, i) => (i === index ? { ...p, ...changes } : p)));

  const removePole = (index) => {
    if (!window.confirm(`Remove Pole ${index + 1}? Cabinets mounted on it are retained for review.`)) return;
    onChange(poles.filter((_, i) => i !== index));
  };

  const addPole = () =>
    onChange([
      ...poles,
      { pole_id: options[0]?.id || "", height_inches: 120, embedment_inches: 42, include_pole_painting: false },
    ]);

  // Legacy item-pole fields ride on the items; they are advisory-only and
  // never part of the priced list this panel edits.
  const consolidated = consolidateFoundationPoles({ items, poles });

  return (
    <div className="space-y-3">
      <div className="flex items-center justify-between">
        <div>
          <h2 className="font-semibold text-gray-900">Poles</h2>
          <p className="text-xs text-gray-500">
            Priced on billed length — an explicit total stock length, or height above grade plus embedment.
          </p>
        </div>
        <Button variant="outline" size="sm" onClick={addPole} disabled={options.length === 0}>
          <Plus className="w-4 h-4" aria-hidden="true" /> Pole
        </Button>
      </div>

      {options.length === 0 && (
        <div className="text-[11px] text-amber-800 bg-amber-50 border border-amber-200 rounded px-2 py-1.5">
          Pole catalog unavailable — existing rows remain editable; new poles cannot be added.
        </div>
      )}
      {consolidated.legacyPoles.length > 0 && (
        <div role="status" className="text-[11px] text-amber-800 bg-amber-50 border border-amber-200 rounded px-2 py-1.5 space-y-1">
          <p className="font-semibold">Legacy item-pole data — not priced</p>
          {consolidated.legacyPoles.map((d) => (
            <div key={d.source_item_component_id || `item-${d.source_item_index}`} className="flex items-center justify-between gap-2">
              <span>
                Foundation {d.source_item_index + 1} carries legacy pole fields
                {d.legacy_pole_cost !== null || d.legacy_pole_painting_cost !== null ? " (with saved amounts)" : ""}.
              </span>
              {typeof onMigrateItemPole === "function" && (
                <Button variant="outline" size="sm" onClick={() => onMigrateItemPole(d.source_item_index)}>
                  Move to Poles
                </Button>
              )}
            </div>
          ))}
          {consolidated.overlaps.length > 0 && (
            <p>A project pole already sits on the same foundation — verify it is not the same physical pole before migrating.</p>
          )}
        </div>
      )}
      {poles.length === 0 ? (
        <div className="text-center py-6 bg-white rounded-xl border border-dashed border-gray-300 text-gray-500 text-sm">
          No poles on this section.
        </div>
      ) : (
        poles.map((pole, index) => {
          const issues = polePricing[index]?.issues || [];
          const pricingUnavailable = polePricing[index]?.available === false;
          const geometry = polePricing[index]?.geometry || null;
          const fieldIssue = (field) => issues.some((i) => i.field === field);
          const describedBy = issues.length ? `pole-${index}-pricing` : undefined;
          const authoredShape = pole.pole_shape ?? "";
          const shapeChoices = authoredShape && !POLE_SHAPE_VALUES.includes(authoredShape)
            ? [authoredShape, ...POLE_SHAPE_VALUES]
            : POLE_SHAPE_VALUES;
          return (
            <div key={pole.component_id || index} className="bg-white rounded-xl border border-gray-200 p-3">
              <div className="grid grid-cols-2 md:grid-cols-4 gap-2 items-end">
                <label className="text-xs text-gray-500 md:col-span-2">
                  Pole
                  <select
                    className="w-full h-9 rounded-md border border-input bg-transparent px-2 text-sm"
                    value={pole.pole_id || ""}
                    aria-label="Pole material"
                    aria-invalid={fieldIssue("pole_id") || undefined}
                    aria-describedby={fieldIssue("pole_id") ? describedBy : undefined}
                    onChange={(e) => patchPole(index, { pole_id: e.target.value })}
                  >
                    <option value="">Select pole…</option>
                    {pole.pole_id && !options.some((o) => o.id === pole.pole_id) && (
                      <option value={pole.pole_id} disabled>{`Catalog pole unavailable (${pole.pole_id})`}</option>
                    )}
                    {options.map((o) => (
                      <option key={o.id} value={o.id}>
                        {o.material_name}
                      </option>
                    ))}
                  </select>
                  {pole.pole_id && !options.some((o) => o.id === pole.pole_id) && (
                    <span className="block text-[10px] text-amber-700 mt-1">Catalog pole unavailable; current pricing needs review.</span>
                  )}
                </label>
                <label className="text-xs text-gray-500">
                  Shape
                  <select
                    className="w-full h-9 rounded-md border border-input bg-transparent px-2 text-sm"
                    value={authoredShape}
                    aria-label={`Pole ${index + 1} cross-section shape`}
                    aria-invalid={fieldIssue("pole_shape") || undefined}
                    aria-describedby={fieldIssue("pole_shape") ? describedBy : undefined}
                    onChange={(e) => patchPole(index, { pole_shape: e.target.value === "" ? undefined : e.target.value })}
                  >
                    <option value="">Catalog / unspecified</option>
                    {shapeChoices.map((s) => (
                      <option key={s} value={s}>{s}</option>
                    ))}
                  </select>
                </label>
                <label className="text-xs text-gray-500">
                  Foundation
                  <select
                    className="w-full h-9 rounded-md border border-input bg-transparent px-2 text-sm"
                    value={pole.foundation_component_id ?? ""}
                    aria-label="Pole foundation"
                    onChange={(e) => {
                      const id = e.target.value;
                      const i = items.findIndex((it) => it.component_id === id);
                      patchPole(index, {
                        foundation_component_id: id,
                        foundation_idx: id === "" || i < 0 ? undefined : i,
                      });
                    }}
                  >
                    <option value="">Unassigned</option>
                    {pole.foundation_component_id && !items.some((it) => it.component_id === pole.foundation_component_id) && (
                      <option value={pole.foundation_component_id} disabled>{`Missing foundation (${String(pole.foundation_component_id).slice(0, 18)}…)`}</option>
                    )}
                    {items.map((it, i) => (
                      <option key={it.component_id || i} value={it.component_id || ""}>
                        {it.description || `Foundation ${i + 1}`}
                      </option>
                    ))}
                  </select>
                </label>
                <label className="text-xs text-gray-500">
                  Height above grade (in)
                  <Input
                    type="number"
                    step="any"
                    value={pole.height_inches ?? ""}
                    aria-label={`Pole ${index + 1} height above grade (inches)`}
                    aria-invalid={fieldIssue("height_inches") || undefined}
                    aria-describedby={fieldIssue("height_inches") ? describedBy : undefined}
                    onChange={(e) => patchPole(index, { height_inches: heightInput(e.target.value) })}
                  />
                </label>
                <label className="text-xs text-gray-500">
                  Embedment below grade (in)
                  <Input
                    type="number"
                    step="any"
                    // A recorded canonical value wins; blank canonical falls
                    // back to the legacy spelling so display matches pricing.
                    value={(pole.embedment_inches !== undefined && pole.embedment_inches !== null && pole.embedment_inches !== "")
                      ? pole.embedment_inches
                      : (pole.y_offset_inches ?? "")}
                    aria-label={`Pole ${index + 1} embedment below grade (inches)`}
                    aria-invalid={fieldIssue("embedment_inches") || fieldIssue("y_offset_inches") || undefined}
                    aria-describedby={(fieldIssue("embedment_inches") || fieldIssue("y_offset_inches")) ? describedBy : undefined}
                    onChange={(e) => patchPole(index, {
                      // Canonical field carries the edit; the legacy spelling
                      // clears so the two can never diverge into a conflict.
                      embedment_inches: heightInput(e.target.value),
                      y_offset_inches: undefined,
                    })}
                  />
                </label>
                <label className="text-xs text-gray-500">
                  Base offset above grade (in)
                  <Input
                    type="number"
                    step="any"
                    value={pole.base_offset_inches ?? ""}
                    aria-label={`Pole ${index + 1} base offset above grade (inches)`}
                    aria-invalid={fieldIssue("base_offset_inches") || undefined}
                    aria-describedby={fieldIssue("base_offset_inches") ? describedBy : undefined}
                    onChange={(e) => patchPole(index, { base_offset_inches: heightInput(e.target.value) })}
                  />
                </label>
                <label className="text-xs text-gray-500">
                  Total stock length (in)
                  <Input
                    type="number"
                    step="any"
                    value={pole.total_length_inches ?? ""}
                    aria-label={`Pole ${index + 1} total stock length (inches)`}
                    aria-invalid={fieldIssue("total_length_inches") || undefined}
                    aria-describedby={fieldIssue("total_length_inches") ? describedBy : undefined}
                    onChange={(e) => patchPole(index, { total_length_inches: heightInput(e.target.value) })}
                  />
                </label>
              </div>

              <div className="flex items-center justify-between mt-2">
                <label className="flex items-center gap-1.5 text-xs font-medium text-gray-700">
                  <input
                    type="checkbox"
                    checked={!!pole.include_pole_painting}
                    aria-invalid={issues.some((i) => i.code === "pole_paint_setting_unavailable") || undefined}
                    aria-describedby={issues.some((i) => i.code === "pole_paint_setting_unavailable") ? describedBy : undefined}
                    onChange={(e) => patchPole(index, { include_pole_painting: e.target.checked })}
                  />
                  Paint pole
                </label>
                <div className="flex items-center gap-3 text-xs text-gray-600">
                  {geometry && Number.isFinite(geometry.required_length_inches) && (
                    <span title={`Required ${geometry.required_length_inches} in${Number.isFinite(pole.stock_pieces) ? ` · ${pole.stock_pieces} stock ${pole.stock_pieces === 1 ? "piece" : "pieces"}` : ""}${geometry.pole_shape ? ` · ${geometry.pole_shape}` : ""}${geometry.base_offset_inches > 0 ? ` · base +${geometry.base_offset_inches} in` : ""}`}>
                      {geometry.required_length_inches} in req
                    </span>
                  )}
                  <span>Pole {hasFoundationCostSnapshot(pole.pole_cost) ? money(pole.pole_cost) : "Not saved"}</span>
                  <span>Paint {hasFoundationCostSnapshot(pole.pole_painting_cost) ? money(pole.pole_painting_cost) : "Not saved"}</span>
                  <span className="font-bold text-gray-900 text-sm">{hasFoundationCostSnapshot(pole.total_cost) ? money(pole.total_cost) : "Not saved"}</span>
                  {pricingUnavailable && <span className="col-span-full text-[10px] text-amber-700">Saved amounts (not current pricing)</span>}
                  <Button variant="ghost" size="icon" onClick={() => removePole(index)}>
                    <Trash2 className="w-4 h-4 text-red-500" aria-hidden="true" />
                  </Button>
                </div>
              </div>
              {issues.length > 0 && (
                <div role="status" className="mt-2 text-[10px] text-amber-700 space-y-0.5" id={`pole-${index}-pricing`}>
                  {issues.map((issue) => <p key={`${issue.field}-${issue.code}`}>{issue.message}</p>)}
                </div>
              )}
            </div>
          );
        })
      )}
    </div>
  );
}

import { useMemo } from "react";
import { money, calcSignageCabinetPricing } from "./foundationCalc";
import { hasFoundationCostSnapshot } from "./foundationCatalogIntegrity";
import { foundationWallBomRows } from "./wallCalculator";
import { landscapeSummary } from "./landscapeMaterials";

const num = (v) => (Number.isFinite(Number(v)) ? Number(v) : 0);
const qty = (n, unit) => `${num(n).toLocaleString(undefined, { maximumFractionDigits: 2 })} ${unit}`;
const EMPTY_ITEMS = [];
const EMPTY_POLES = [];
const EMPTY_WALLS = [];
const EMPTY_TOTALS = {};
const EMPTY_INVENTORY = [];

export default function FoundationBOM({
  items = EMPTY_ITEMS,
  poles = EMPTY_POLES,
  walls = EMPTY_WALLS,
  delivery,
  totals = EMPTY_TOTALS,
  inventory = EMPTY_INVENTORY,
  itemPricing = EMPTY_ITEMS,
  polePricing = EMPTY_ITEMS,
  wallPricing = EMPTY_ITEMS,
  cabinets = EMPTY_ITEMS,
  landscape,
  landscapePricing,
  pricingUnavailable = false,
}) {
  const cabinetRows = useMemo(() => calcSignageCabinetPricing(cabinets), [cabinets]);
  const rows = useMemo(() => {
    const out = [];
    // rawQty is the real numeric quantity; displayQty is the formatted label.
    // A row with a positive quantity OR a known cost stays listed (free rows
    // included) — the formatted string is never parsed for the drop test.
    const add = (material, displayQty, cost, rawQty = num(displayQty)) => {
      if (num(rawQty) <= 0 && !hasFoundationCostSnapshot(cost)) return;
      out.push({ material, quantity: displayQty, cost });
    };
    const nameOf = (id) => inventory.find((i) => i.id === id)?.material_name || "Material";
    const resolved = items.filter((_, i) => itemPricing[i]?.available !== false);
    const blocked = items.filter((_, i) => itemPricing[i]?.available === false);

    if (delivery?.pricingUnavailable) {
      out.push({
        material: "Concrete delivery/order (saved)",
        quantity: Number.isFinite(delivery.roundedYards) ? qty(delivery.roundedYards, "CY") : "Not saved",
        cost: hasFoundationCostSnapshot(delivery.concreteTotal) ? delivery.concreteTotal : "Not saved",
        saved: true,
      });
    } else if (num(delivery?.roundedYards) > 0) {
      add("Ready-mix concrete (delivered)", qty(delivery.roundedYards, "CY"), delivery.concreteTotal, delivery.roundedYards);
    }
    const bags = resolved.reduce((s, i) => s + num(i.concrete_bags), 0);
    const baggedCost = resolved.reduce((s, i) => s + num(i.concrete_cost), 0);
    if (bags > 0 || baggedCost > 0) add("Bagged concrete", qty(bags, "bags"), baggedCost, bags);

    const rebarFt = resolved.reduce((s, i) => s + num(i.rebar_feet), 0);
    const rebarLbs = resolved.reduce((s, i) => s + num(i.rebar_weight_lbs), 0);
    const rebarCost = resolved.reduce((s, i) => s + num(i.rebar_cost), 0);
    if (rebarFt > 0) {
      add(`Rebar (${qty(rebarLbs, "lbs")})`, qty(rebarFt, "LF"), rebarCost, rebarFt);
    }

    const formingQty = resolved.reduce((s, i) => s + num(i.forming_qty), 0);
    const formingCost = resolved.reduce((s, i) => s + num(i.forming_cost), 0);
    if (formingQty > 0) add("Forming material", qty(formingQty, "units"), formingCost, formingQty);

    blocked.forEach((i) => {
      const label = `Foundation ${i.component_id ?? "?"} (saved)`;
      {
        out.push({
          material: `${label} — concrete`,
          quantity: Number.isFinite(i.concrete_bags) ? qty(i.concrete_bags, "bags") : "Not saved",
          cost: hasFoundationCostSnapshot(i.concrete_cost) ? i.concrete_cost : "Not saved",
          saved: true,
        });
      }
      if (i.include_rebar) {
        out.push({
          material: `${label} — rebar`,
          quantity: Number.isFinite(i.rebar_feet) ? qty(i.rebar_feet, "LF") : "Not saved",
          cost: hasFoundationCostSnapshot(i.rebar_cost) ? i.rebar_cost : "Not saved",
          saved: true,
        });
      }
      if (i.include_forming) {
        out.push({
          material: `${label} — forming`,
          quantity: Number.isFinite(i.forming_qty) ? qty(i.forming_qty, "units") : "Not saved",
          cost: hasFoundationCostSnapshot(i.forming_cost) ? i.forming_cost : "Not saved",
          saved: true,
        });
      }
    });

    const poleGroups = {};
    poles.forEach((p, index) => {
      // Held poles list their acknowledged amounts separately, never dropped.
      if (polePricing[index]?.available === false) return;
      if (!p.pole_id) return;
      poleGroups[p.pole_id] = poleGroups[p.pole_id] || { ft: 0, cost: 0 };
      // Billed length is the distinct required-length snapshot (explicit total
      // stock length, or height + embedment); the legacy y_offset_inches
      // spelling of embedment is the fallback for pre-CMP-E02 rows.
      const billedInches = hasFoundationCostSnapshot(p.required_length_inches)
        ? p.required_length_inches
        : num(p.height_inches) + num(p.embedment_inches ?? p.y_offset_inches);
      poleGroups[p.pole_id].ft += billedInches / 12;
      poleGroups[p.pole_id].cost += num(p.pole_cost);
    });
    Object.entries(poleGroups).forEach(([id, g]) => add(nameOf(id), qty(g.ft, "LF"), g.cost, g.ft));

    const polePainting = poles.reduce((s, p, index) =>
      polePricing[index]?.available === false ? s : s + num(p.pole_painting_cost), 0);
    if (polePainting > 0) {
      add("Pole painting", "—", polePainting);
    }

    const savedPoleFt = (p) => {
      const req = Number(p.required_length_inches);
      if (Number.isFinite(req) && req > 0) return req / 12;
      const h = Number(p.height_inches), d = Number(p.embedment_inches ?? p.y_offset_inches);
      return Number.isFinite(h) && h > 0 && Number.isFinite(d) && d >= 0 ? (h + d) / 12 : null;
    };
    poles.forEach((p, index) => {
      if (polePricing[index]?.available !== false) return;
      const label = `Pole ${index + 1} (saved)`;
      const ft = savedPoleFt(p);
      out.push({
        material: `${label} — pole`,
        quantity: Number.isFinite(ft) ? qty(ft, "LF") : "Not saved",
        cost: hasFoundationCostSnapshot(p.pole_cost) ? p.pole_cost : "Not saved",
        saved: true,
      });
      if (p.include_pole_painting || hasFoundationCostSnapshot(p.pole_painting_cost)) {
        out.push({
          material: `${label} — painting`,
          quantity: "—",
          cost: hasFoundationCostSnapshot(p.pole_painting_cost) ? p.pole_painting_cost : "Not saved",
          saved: true,
        });
      }
    });

    out.push(...foundationWallBomRows(walls, inventory, wallPricing));

    (totals.wall_caps_by_material || []).forEach((g) => add(g.name || "Wall cap", qty(g.qty, "pcs"), g.cost, g.qty));

    // Signage cabinets — a priced row lists at the acknowledged unit cost ×
    // quantity; a held row lists its saved state like the blocked foundation
    // items above (never a silently repriced $0 line).
    cabinetRows.forEach((row, index) => {
      const cabinet = cabinets[index] || {};
      const label = cabinet.description || `Signage cabinet ${index + 1}`;
      if (row.available === false) {
        const recordedQty = Number(cabinet.quantity);
        out.push({
          material: `${label} (saved)`,
          quantity: Number.isFinite(recordedQty) ? qty(recordedQty, "pcs") : "Not saved",
          cost: "Not saved",
          saved: true,
        });
        return;
      }
      const quantity = cabinet.quantity === undefined || cabinet.quantity === null || cabinet.quantity === ""
        ? 1
        : Number(cabinet.quantity);
      add(label, qty(quantity, "pcs"), row.cost, quantity);
    });

    // Landscape / site materials — a fully priced grid lists one row per
    // material; a held grid keeps the acknowledged section total as a single
    // saved row, exactly like the saved concrete-delivery row above.
    if (landscapePricing && landscapePricing.available === false) {
      out.push({
        material: "Site landscaping (saved)",
        quantity: "—",
        cost: hasFoundationCostSnapshot(totals.total_landscape_cost) ? totals.total_landscape_cost : "Not saved",
        saved: true,
      });
    } else {
      landscapeSummary(landscape).lines.forEach((line) => {
        if (line.cost === null || line.sqft === null) {
          out.push({
            material: `Site — ${line.label} (saved)`,
            quantity: Number.isFinite(line.sqft) ? qty(line.sqft, "sq ft") : qty(line.cells, "cells"),
            cost: "Not saved",
            saved: true,
          });
          return;
        }
        add(`Site — ${line.label}`, qty(line.sqft, "sq ft"), line.cost, line.sqft);
      });
    }

    return out;
  }, [items, poles, walls, delivery, totals, inventory, itemPricing, polePricing, wallPricing, cabinets, cabinetRows, landscape, landscapePricing]);

  const materialTotal = rows.every(r => hasFoundationCostSnapshot(r.cost)) ? rows.reduce((sum, row) => sum + row.cost, 0) : null;

  return (
    <div className="bg-white rounded-xl border border-gray-200 p-4">
      <h3 className="font-semibold text-gray-900 mb-3">Bill of Materials</h3>
      {pricingUnavailable && (
        <div className="mb-3 rounded-sm border border-amber-300 bg-amber-50 px-2 py-1">
          <p className="text-[11px] font-semibold text-amber-800">Pricing unavailable — saved quantities may be outdated.</p>
          {itemPricing.filter(p => p && p.available === false)
            .concat(polePricing.filter(p => p && p.available === false))
            .concat(cabinetRows.filter(p => p && p.available === false))
            .concat(landscapePricing && landscapePricing.available === false ? [landscapePricing] : [])
            .flatMap((p, k) =>
            (p.issues || []).map((i, j) => <p key={`${k}-${j}`} className="text-[10px] text-amber-700">{i.message}</p>)
          )}
        </div>
      )}
      {rows.length === 0 ? (
        <p className="text-sm text-gray-500">No materials yet — add a foundation to build the list.</p>
      ) : (
        <>
          <table className="w-full text-sm">
            <thead>
              <tr className="text-left text-xs text-gray-500 border-b border-gray-200">
                <th className="py-1.5">Material</th>
                <th className="py-1.5">Quantity</th>
                <th className="py-1.5 text-right">Cost</th>
              </tr>
            </thead>
            <tbody>
              {rows.map((r, i) => (
                <tr key={i} className="border-b border-gray-100 last:border-0">
                  <td className="py-1.5 pr-3 text-gray-800">{r.material}</td>
                  <td className="py-1.5 pr-3 whitespace-nowrap text-gray-600">{r.quantity}</td>
                  <td className="py-1.5 pl-3 whitespace-nowrap text-right text-gray-900">{hasFoundationCostSnapshot(r.cost) ? money(r.cost) : "Not saved"}</td>
                </tr>
              ))}
            </tbody>
          </table>
          <div className="flex justify-between pt-3 mt-1 border-t border-gray-200 font-bold text-gray-900">
            <span>Listed cost subtotal</span>
            <span>{pricingUnavailable ? <span className="text-amber-700">Pricing unavailable</span> : hasFoundationCostSnapshot(materialTotal) ? money(materialTotal) : "Not saved"}</span>
          </div>
        </>
      )}
    </div>
  );
}

import { useEffect, useRef, useState } from "react";
import * as THREE from "three";
import { Maximize2, RotateCcw, Eye, EyeOff, Box } from "lucide-react";

const IN = 1 / 12; // inches -> feet units

function buildScene(scene, project, solid, showGround) {
  const group = new THREE.Group();

  const concreteMat = solid
    ? new THREE.MeshStandardMaterial({ color: 0x9ca3af, roughness: 0.9 })
    : new THREE.MeshBasicMaterial({ color: 0x374151, wireframe: true });
  const poleMat = solid
    ? new THREE.MeshStandardMaterial({ color: 0x4b5563, metalness: 0.4, roughness: 0.5 })
    : new THREE.MeshBasicMaterial({ color: 0x1f2937, wireframe: true });

  let cursorX = 0;
  const items = project.items || [];
  items.forEach((item) => {
    const qty = Math.max(1, Number(item.quantity) || 1);
    const depth = (Number(item.depth_inches) || 0) * IN;
    for (let i = 0; i < qty; i++) {
      let mesh;
      let footprint;
      if (item.foundation_type === "pillar") {
        const r = ((Number(item.diameter) || 0) / 2) * IN;
        footprint = r * 2;
        mesh = new THREE.Mesh(new THREE.CylinderGeometry(r, r, depth, 24), concreteMat);
      } else {
        const l = (Number(item.length_inches) || 0) * IN;
        const w = (Number(item.width_inches) || 0) * IN;
        footprint = Math.max(l, w);
        mesh = new THREE.Mesh(new THREE.BoxGeometry(l, depth, w), concreteMat);
      }
      const offset = (Number(item.grade_offset_inches) || 0) * IN;
      mesh.position.set(cursorX + footprint / 2, -depth / 2 + offset, 0);
      mesh.rotation.y = ((Number(item.rotation_degrees) || 0) * Math.PI) / 180;
      group.add(mesh);

      if (item.selected_pole_id || item.pole_total_height_inches) {
        const h = (Number(item.pole_total_height_inches) || 96) * IN;
        const pole = new THREE.Mesh(new THREE.CylinderGeometry(0.35, 0.35, h, 16), poleMat);
        pole.position.set(mesh.position.x, offset + h / 2, 0);
        group.add(pole);
      }

      cursorX += footprint + 2;
    }
  });

  (project.poles || []).forEach((p) => {
    // CMP-E02: distinct quantities — the pole top sits at base offset plus
    // height above grade; embedment extends BELOW grade (canonical
    // embedment_inches; the legacy y_offset_inches spelling carries the same
    // authored "depth in ground" quantity and is no longer read as an upward
    // elevation — CMP-AUD07). Cross-section follows the authored/resolved
    // pole_shape; unspecified stays the round default.
    const height = (Number(p.height_inches) || 96) * IN;
    const embed = (Number(p.embedment_inches ?? p.y_offset_inches) || 0) * IN;
    const base = (Number(p.base_offset_inches) || 0) * IN;
    const len = height + embed;
    const shape = typeof p.pole_shape === "string" ? p.pole_shape.toLowerCase() : "round";
    let pole;
    if (shape === "square" || shape === "rectangular") {
      pole = new THREE.Mesh(new THREE.BoxGeometry(0.7, len, shape === "rectangular" ? 0.45 : 0.7), poleMat);
    } else {
      pole = new THREE.Mesh(new THREE.CylinderGeometry(0.35, 0.35, len, 16), poleMat);
      if (shape === "elliptical") pole.scale.z = 0.55;
    }
    pole.position.set(
      (Number(p.x_inches) || 0) * IN,
      base + (height - embed) / 2,
      (Number(p.z_inches) || 0) * IN
    );
    group.add(pole);
  });

  if (showGround) {
    const grid = new THREE.GridHelper(60, 60, 0xd1d5db, 0xe5e7eb);
    grid.position.y = 0.01;
    group.add(grid);
    const ground = new THREE.Mesh(
      new THREE.PlaneGeometry(60, 60),
      new THREE.MeshStandardMaterial({ color: 0xf3f4f6, roughness: 1 })
    );
    ground.rotation.x = -Math.PI / 2;
    group.add(ground);
  }

  // center the model horizontally
  const box = new THREE.Box3().setFromObject(group);
  const center = box.getCenter(new THREE.Vector3());
  group.position.x -= center.x;
  group.position.z -= center.z;

  scene.add(group);
  return group;
}

export default function Foundation3DPreview({ project }) {
  const mountRef = useRef(null);
  const stateRef = useRef({});
  const [solid, setSolid] = useState(true);
  const [showGround, setShowGround] = useState(true);
  const [visible, setVisible] = useState(true);
  const [zoom, setZoom] = useState(100);

  useEffect(() => {
    if (!visible || !mountRef.current) return;
    const mount = mountRef.current;
    const width = mount.clientWidth;
    const height = mount.clientHeight;

    const scene = new THREE.Scene();
    scene.background = new THREE.Color(0xf9fafb);
    const camera = new THREE.PerspectiveCamera(45, width / height, 0.1, 2000);
    const renderer = new THREE.WebGLRenderer({ antialias: true });
    renderer.setPixelRatio(window.devicePixelRatio);
    renderer.setSize(width, height);
    mount.appendChild(renderer.domElement);

    scene.add(new THREE.HemisphereLight(0xffffff, 0x9ca3af, 1.1));
    const dir = new THREE.DirectionalLight(0xffffff, 0.7);
    dir.position.set(20, 30, 20);
    scene.add(dir);

    const st = stateRef.current;
    st.theta = st.theta ?? Math.PI / 4;
    st.phi = st.phi ?? Math.PI / 3.2;
    st.radius = st.radius ?? 30;
    st.target = st.target || new THREE.Vector3(0, 0, 0);

    const applyCamera = () => {
      const r = st.radius;
      camera.position.set(
        st.target.x + r * Math.sin(st.phi) * Math.cos(st.theta),
        st.target.y + r * Math.cos(st.phi),
        st.target.z + r * Math.sin(st.phi) * Math.sin(st.theta)
      );
      camera.lookAt(st.target);
    };

    buildScene(scene, project, solid, showGround);
    applyCamera();

    let frame;
    const render = () => {
      renderer.render(scene, camera);
      frame = requestAnimationFrame(render);
    };
    render();

    // --- controls ---
    let dragging = null;
    let last = { x: 0, y: 0 };
    const onDown = (e) => {
      dragging = e.button === 2 ? "pan" : "orbit";
      last = { x: e.clientX, y: e.clientY };
      e.preventDefault();
    };
    const onMove = (e) => {
      if (!dragging) return;
      const dx = e.clientX - last.x;
      const dy = e.clientY - last.y;
      last = { x: e.clientX, y: e.clientY };
      if (dragging === "orbit") {
        st.theta += dx * 0.008;
        st.phi = Math.min(Math.PI / 2.02, Math.max(0.15, st.phi - dy * 0.006));
      } else {
        const panScale = st.radius * 0.0015;
        st.target.x -= dx * panScale * Math.cos(st.theta + Math.PI / 2);
        st.target.z -= dx * panScale * Math.sin(st.theta + Math.PI / 2);
        st.target.y += dy * panScale;
      }
      applyCamera();
    };
    const onUp = () => (dragging = null);
    const onWheel = (e) => {
      e.preventDefault();
      st.radius = Math.min(200, Math.max(3, st.radius * (1 + e.deltaY * 0.001)));
      setZoom(Math.round((30 / st.radius) * 100));
      applyCamera();
    };
    const onContext = (e) => e.preventDefault();

    const el = renderer.domElement;
    el.addEventListener("mousedown", onDown);
    window.addEventListener("mousemove", onMove);
    window.addEventListener("mouseup", onUp);
    el.addEventListener("wheel", onWheel, { passive: false });
    el.addEventListener("contextmenu", onContext);

    const onResize = () => {
      const w = mount.clientWidth;
      const h = mount.clientHeight;
      camera.aspect = w / h;
      camera.updateProjectionMatrix();
      renderer.setSize(w, h);
    };
    window.addEventListener("resize", onResize);

    stateRef.current.setView = (view) => {
      if (view === "front") { st.theta = -Math.PI / 2; st.phi = Math.PI / 2.05; }
      if (view === "side") { st.theta = 0; st.phi = Math.PI / 2.05; }
      if (view === "top") { st.theta = -Math.PI / 2; st.phi = 0.16; }
      if (view === "reset") {
        st.theta = Math.PI / 4;
        st.phi = Math.PI / 3.2;
        st.radius = 30;
        st.target.set(0, 0, 0);
        setZoom(100);
      }
      applyCamera();
    };

    return () => {
      cancelAnimationFrame(frame);
      el.removeEventListener("mousedown", onDown);
      window.removeEventListener("mousemove", onMove);
      window.removeEventListener("mouseup", onUp);
      el.removeEventListener("wheel", onWheel);
      el.removeEventListener("contextmenu", onContext);
      window.removeEventListener("resize", onResize);
      renderer.dispose();
      if (el.parentNode === mount) mount.removeChild(el);
    };
  }, [project, solid, showGround, visible]);

  const setView = (v) => stateRef.current.setView?.(v);

  const ToolBtn = ({ children, onClick, active }) => (
    <button
      type="button"
      onClick={onClick}
      className={`h-[24px] px-2 rounded-sm border text-[11px] font-medium flex items-center gap-1 ${
        active ? "bg-blue-600 border-blue-600 text-white" : "bg-white border-gray-300 text-gray-700"
      }`}
    >
      {children}
    </button>
  );

  return (
    <div className="bg-white border border-gray-200 rounded-sm p-2">
      <div className="flex items-center justify-between mb-2">
        <div>
          <span className="text-[12px] font-bold text-gray-800">3D Preview</span>
          <span className="text-[11px] text-gray-400 ml-2">Updates live as you edit</span>
        </div>
        <button
          type="button"
          onClick={() => setVisible((v) => !v)}
          className="text-[11px] font-medium text-gray-600 hover:text-red-600 flex items-center gap-1"
        >
          {visible ? <EyeOff className="w-3.5 h-3.5" aria-hidden="true" /> : <Eye className="w-3.5 h-3.5" aria-hidden="true" />}
          {visible ? "Hide 3D View" : "Show 3D View"}
        </button>
      </div>

      {visible && (
        <>
          <div className="flex items-center gap-1 flex-wrap mb-2">
            <ToolBtn onClick={() => setView("front")}>Front</ToolBtn>
            <ToolBtn onClick={() => setView("side")}>Side</ToolBtn>
            <ToolBtn onClick={() => setView("top")}>Top</ToolBtn>
            <ToolBtn onClick={() => setView("reset")}>
              <RotateCcw className="w-3 h-3" aria-hidden="true" /> Reset
            </ToolBtn>
            <span className="text-[11px] text-gray-500 px-1">{zoom}%</span>
            <ToolBtn onClick={() => setShowGround((v) => !v)} active={!showGround}>
              {showGround ? "Hide Ground" : "Show Ground"}
            </ToolBtn>
            <ToolBtn onClick={() => setSolid((v) => !v)} active={solid}>
              <Box className="w-3 h-3" aria-hidden="true" /> {solid ? "Solid Mode" : "Wireframe"}
            </ToolBtn>
            <ToolBtn onClick={() => mountRef.current?.requestFullscreen?.()}>
              <Maximize2 className="w-3 h-3" aria-hidden="true" /> Full Screen
            </ToolBtn>
          </div>

          <div ref={mountRef} className="w-full h-[420px] rounded-sm overflow-hidden bg-gray-50" />

          <div className="flex items-center justify-between text-[10px] text-gray-500 mt-1 px-1">
            <span>Left Click + Drag: Orbit/Rotate</span>
            <span>Right Click + Drag: Pan/Move</span>
            <span>Scroll Wheel: Zoom in/out</span>
          </div>
        </>
      )}
    </div>
  );
}

